using System.Collections.Immutable;
using KuaiYi.Core;
using KuaiYi.Core.Settings;
using Xunit;
namespace KuaiYi.Core.Tests;
public sealed class HotkeyTests
{
    internal sealed class Port:IHotkeyRegistrar
    {
        public readonly Dictionary<int,HotkeyChord> Owned=[];public readonly HashSet<HotkeyChord> Foreign=[];public readonly List<(string Op,int Id,HotkeyChord? Chord)> Calls=[];public uint Now=100;public Action? BeforeFence;public Func<string,int,HotkeyChord?,int>? Failure;
        public HotkeyRegistrationResult Register(int id,HotkeyChord chord){Calls.Add(("register",id,chord));int error=Failure?.Invoke("register",id,chord)??0;if(error!=0)return new(false,error);if(Foreign.Contains(chord)||Owned.Values.Contains(chord))return new(false,1409);Owned.Add(id,chord);return new(true,0);}
        public HotkeyRegistrationResult Unregister(int id){Calls.Add(("unregister",id,null));int error=Failure?.Invoke("unregister",id,null)??0;if(error!=0)return new(false,error);return Owned.Remove(id)?new(true,0):new(false,1419);}
        public uint FenceInput(){Calls.Add(("fence",0,null));BeforeFence?.Invoke();if((Failure?.Invoke("fence",0,null)??0)!=0)throw new IOException("Public injected fence failure.");return Now;}
    }
    internal static ImmutableDictionary<string,string?> Map(params (string Action,string? Chord)[] keys){var values=AppSettings.DefaultHotkeys.ToImmutableDictionary(p=>p.Key,_=>(string?)null);foreach(var key in keys)values=values.SetItem(key.Action,key.Chord);return values;}
    [Theory][InlineData("Ctrl+Alt+T","Ctrl+Alt+T")][InlineData("control + shift + f24","Ctrl+Shift+F24")][InlineData("Alt+Q","Alt+Q")][InlineData("Ctrl+Space","Ctrl+Space")][InlineData("Alt+Shift+PageDown","Alt+Shift+PageDown")][InlineData("Ctrl+1","Ctrl+1")]
    public void SupportedChordNormalization(string text,string expected)=>Assert.Equal(expected,HotkeyPolicy.Parse(text).Text);
    [Theory][InlineData("A")][InlineData("Ctrl")][InlineData("Shift+A")][InlineData("Win+Q")][InlineData("Ctrl+Ctrl+T")][InlineData("Ctrl+F12")][InlineData("Alt+F4")][InlineData("Alt+Shift+F4")][InlineData("Alt+Tab")][InlineData("Ctrl+Alt+Tab")][InlineData("Alt+Shift+Tab")][InlineData("Ctrl+Alt+Delete")][InlineData("Ctrl+Alt+Shift+Delete")][InlineData("Ctrl+Shift+Escape")][InlineData("Ctrl+Escape")][InlineData("Alt+Space")][InlineData("Ctrl+PrintScreen")][InlineData("Ctrl+F25")][InlineData("Ctrl++")][InlineData("")]
    public void UnsupportedAndReservedKeysNeverReachOs(string text)=>Assert.Throws<HotkeyValidationException>(()=>HotkeyPolicy.Parse(text));
    [Theory][InlineData("toggle")][InlineData("translateSelection")][InlineData("captureRegion")][InlineData("toggleResult")][InlineData("regenerate")][InlineData("hideOverlay")][InlineData("focusResult")][InlineData("openSettings")][InlineData("stopGeneration")]
    public void EveryActionSupportsRecordClearAndSuggestedRestore(string action)
    {var record=new HotkeyRecorder();Assert.Null(record.Record(HotkeyModifiers.Control,0x51));record.Begin();Assert.Equal("Ctrl+Q",record.Record(HotkeyModifiers.Control,0x51)!.Value.Text);Assert.Null(record.Record(HotkeyModifiers.Control,0x51,true));record.End();Assert.Null(record.Record(HotkeyModifiers.Control,0x51));var cleared=Map((action,null));Assert.Empty(HotkeyPolicy.ValidateMap(cleared));var suggested=Map((action,AppSettings.DefaultHotkeys[action]));Assert.Equal(AppSettings.DefaultHotkeys[action]!=null?1:0,HotkeyPolicy.ValidateMap(suggested).Count);}
    [Theory][InlineData(0x10)][InlineData(0x11)][InlineData(0x12)][InlineData(0x5b)][InlineData(0x5c)][InlineData(0xa4)]
    public void ModifierOnlyRecordingCannotBecomeChord(int key){var record=new HotkeyRecorder();record.Begin();Assert.Null(record.Record(HotkeyModifiers.Control,(uint)key));}
    [Fact]public void InternalDuplicateCanonicalChordReportsBothActionsBeforeOs()
    {var port=new Port();var registry=new HotkeyRegistry(port);var error=Assert.Throws<HotkeyValidationException>(()=>registry.Prepare(Map(("toggle","Ctrl+Alt+Q"),("translateSelection","alt+control+q"))));Assert.Contains("duplicate:",error.Problem);Assert.Empty(port.Calls);}
    [Fact]public void AllDefaultActionsValidateAndAltGrRiskIsExplicit(){Assert.Equal(5,HotkeyPolicy.ValidateMap(AppSettings.DefaultHotkeys).Count);Assert.True(HotkeyPolicy.Parse("Ctrl+Alt+T").AltGrRisk);Assert.False(HotkeyPolicy.Parse("Ctrl+Shift+T").AltGrRisk);}
    [Fact]public void NewChordRegistersBeforeOriginalIsReleasedAndPendingMessagesDoNotDispatch()
    {var port=new Port();var registry=new HotkeyRegistry(port);registry.Restore(Map(("toggle","Ctrl+Q")),"old");int old=port.Owned.Single().Key;var signal=registry.Resolve(old,HotkeyPolicy.Parse("Ctrl+Q"),101)!;port.Calls.Clear();var transaction=registry.Prepare(Map(("toggle","Ctrl+T")));Assert.Equal("register",port.Calls[0].Op);Assert.Equal("unregister",port.Calls[1].Op);Assert.False(registry.Current(signal));Assert.Null(registry.Resolve(port.Owned.Single().Key,HotkeyPolicy.Parse("Ctrl+T"),101));registry.Commit(transaction,"new");var current=registry.Resolve(port.Owned.Single().Key,HotkeyPolicy.Parse("Ctrl+T"),101)!;Assert.Equal("new",current.SettingsVersion);Assert.True(registry.Current(current));}
    [Theory][InlineData(1)][InlineData(2)]
    public void FailedNewRegistrationPreservesAllOriginalKeysAndForeignChord(int failAt)
    {var port=new Port();var registry=new HotkeyRegistry(port);var original=Map(("toggle","Ctrl+Q"),("openSettings","Ctrl+W"));registry.Restore(original,"old");var owned=port.Owned.ToDictionary();int attempts=0;port.Calls.Clear();port.Failure=(op,_,_)=>op=="register"&&++attempts==failAt?1409:0;var error=Assert.Throws<HotkeyRegistrationException>(()=>registry.Prepare(Map(("toggle","Ctrl+T"),("openSettings","Ctrl+S"))));Assert.Equal(1409,error.Error);Assert.Equal(owned.OrderBy(p=>p.Key),port.Owned.OrderBy(p=>p.Key));Assert.DoesNotContain(port.Calls,c=>c.Op=="unregister"&&owned.ContainsKey(c.Id));}
    [Fact]public void GroupSwapReusesBindingsAndOldQueueCannotInvokeNewAction()
    {var port=new Port();var registry=new HotkeyRegistry(port);registry.Restore(Map(("toggle","Ctrl+Q"),("openSettings","Ctrl+W")),"old");var original=port.Owned.ToDictionary();int q=port.Owned.Single(p=>p.Value==HotkeyPolicy.Parse("Ctrl+Q")).Key;var prior=registry.Resolve(q,HotkeyPolicy.Parse("Ctrl+Q"),101)!;port.Calls.Clear();port.Now=200;var transaction=registry.Prepare(Map(("toggle","Ctrl+W"),("openSettings","Ctrl+Q")));registry.Commit(transaction,"new");Assert.Equal(original.OrderBy(p=>p.Key),port.Owned.OrderBy(p=>p.Key));Assert.DoesNotContain(port.Calls,c=>c.Op is "register" or "unregister");Assert.False(registry.Current(prior));Assert.Null(registry.Resolve(q,HotkeyPolicy.Parse("Ctrl+Q"),199));Assert.Null(registry.Resolve(q,HotkeyPolicy.Parse("Ctrl+Q"),200));Assert.Equal("openSettings",registry.Resolve(q,HotkeyPolicy.Parse("Ctrl+Q"),201)!.Action);}
    [Fact]public void ClearAndRollbackRestoreOriginalIdsAndIgnoreCandidateSignal()
    {var port=new Port();var registry=new HotkeyRegistry(port);var original=Map(("toggle","Ctrl+Q"),("openSettings","Ctrl+W"));registry.Restore(original,"old");var owned=port.Owned.ToDictionary();var transaction=registry.Prepare(Map());Assert.Empty(port.Owned);registry.Rollback(transaction);Assert.Equal(owned.OrderBy(p=>p.Key),port.Owned.OrderBy(p=>p.Key));Assert.All(registry.Status.Where(s=>s.Chord!=null),s=>Assert.True(s.Registered));}
    [Fact]public void FailedOldReleaseRollsBackCompletePhysicalSet()
    {var port=new Port();var registry=new HotkeyRegistry(port);registry.Restore(Map(("toggle","Ctrl+Q"),("openSettings","Ctrl+W")),"old");var original=port.Owned.ToDictionary();int removals=0;port.Failure=(op,id,_)=>op=="unregister"&&original.ContainsKey(id)&&++removals==2?5:0;Assert.Throws<HotkeyRegistrationException>(()=>registry.Prepare(Map(("toggle","Ctrl+T"),("openSettings","Ctrl+S"))));Assert.Equal(original.OrderBy(p=>p.Key),port.Owned.OrderBy(p=>p.Key));}
    [Fact]public void UnconfirmedRollbackRetainsOnlyOwnedIdsAndDisablesDispatch()
    {var port=new Port();var registry=new HotkeyRegistry(port);registry.Restore(Map(("toggle","Ctrl+Q")),"old");var transaction=registry.Prepare(Map(("toggle","Ctrl+T")));port.Foreign.Add(HotkeyPolicy.Parse("Ctrl+Q"));Assert.Throws<AggregateException>(()=>registry.Rollback(transaction));Assert.All(registry.Status,s=>Assert.True(s.RecoveryRequired));Assert.Contains(HotkeyPolicy.Parse("Ctrl+Q"),port.Foreign);Assert.Throws<HotkeyRegistryStateException>(()=>registry.Prepare(Map()));Assert.Null(registry.Resolve(123,HotkeyPolicy.Parse("Ctrl+T"),101));}
    [Fact]public void FirstLaunchFailureRecordsActualErrorWithoutFallbackOrOwnerGuess()
    {var port=new Port();port.Foreign.Add(HotkeyPolicy.Parse("Ctrl+Alt+T"));var registry=new HotkeyRegistry(port);registry.Restore(AppSettings.DefaultHotkeys,"saved");var toggle=registry.Status.Single(s=>s.Action=="toggle");Assert.False(toggle.Registered);Assert.Equal(1409,toggle.Error);Assert.Equal("Ctrl+Alt+T",toggle.Chord!.Value.Text);Assert.Equal(4,port.Owned.Count);Assert.Single(port.Foreign);}
    [Fact]public void UnlockOrExplorerRecoveryKeepsWorkingCombosAndRetriesOnlyMissingOnes()
    {var port=new Port();var q=HotkeyPolicy.Parse("Ctrl+Q");port.Foreign.Add(q);var registry=new HotkeyRegistry(port);registry.Restore(Map(("toggle","Ctrl+Q"),("openSettings","Ctrl+W")),"saved");int old=port.Owned.Single().Key;registry.Suspend(true);Assert.Null(registry.Resolve(old,HotkeyPolicy.Parse("Ctrl+W"),101));port.Foreign.Clear();port.Calls.Clear();registry.Suspend(false);registry.Recover("saved");Assert.Equal(2,port.Owned.Count);Assert.Contains(old,port.Owned.Keys);Assert.Single(port.Calls,c=>c.Op=="register");Assert.DoesNotContain(port.Calls,c=>c.Op=="unregister");Assert.All(registry.Status.Where(s=>s.Chord!=null),s=>Assert.True(s.Registered));}
    [Theory][InlineData(0xfffffff0u,0x10u,true)][InlineData(100u,99u,false)][InlineData(100u,100u,false)][InlineData(100u,101u,true)]
    public void MessageFenceHandlesWrapAndRejectsPreCommitEvents(uint fence,uint tick,bool accepted)
    {var port=new Port{Now=fence};var registry=new HotkeyRegistry(port);registry.Restore(Map(("toggle","Ctrl+Q")),"saved");Assert.Equal(accepted,registry.Resolve(port.Owned.Single().Key,HotkeyPolicy.Parse("Ctrl+Q"),tick)!=null);}
    [Theory][InlineData("translateSelection",HotkeyActionDecision.HintEnable)][InlineData("regenerate",HotkeyActionDecision.HintEnable)][InlineData("captureRegion",HotkeyActionDecision.Run)][InlineData("toggleResult",HotkeyActionDecision.Run)][InlineData("hideOverlay",HotkeyActionDecision.Run)][InlineData("focusResult",HotkeyActionDecision.Run)][InlineData("openSettings",HotkeyActionDecision.Run)][InlineData("toggle",HotkeyActionDecision.Run)][InlineData("stopGeneration",HotkeyActionDecision.Run)]
    public void OffActionPolicyNeverAutomaticallyTranslates(string action,HotkeyActionDecision expected)=>Assert.Equal(expected,HotkeyActionPolicy.Evaluate(action,Activation.Off,Suspension.None));
    [Theory][InlineData("toggle")][InlineData("translateSelection")][InlineData("captureRegion")][InlineData("regenerate")][InlineData("openSettings")][InlineData("hideOverlay")]
    public void LockedActionIsAlwaysBlocked(string action)=>Assert.Equal(HotkeyActionDecision.Blocked,HotkeyActionPolicy.Evaluate(action,Activation.On,Suspension.SessionLocked));
    [Fact]public void CleanupFailureIsReportedAndOriginalIdsAreRetainedForRetry()
    {var port=new Port();var registry=new HotkeyRegistry(port);registry.Restore(Map(("toggle","Ctrl+Q")),"saved");port.Failure=(op,_,_)=>op=="unregister"?5:0;Assert.Throws<AggregateException>(registry.Close);Assert.Single(port.Owned);port.Failure=null;registry.Close();Assert.Empty(port.Owned);}
    [Theory][InlineData("reconcile")][InlineData("unlock")][InlineData("recover")]
    public void ReentrantSentMessageCannotDispatchWhileNativeQueueFenceIsBeingEstablished(string transition)
    {var port=new Port();var registry=new HotkeyRegistry(port);var values=Map(("toggle","Ctrl+Q"));registry.Restore(values,"v1");int id=port.Owned.Single().Key;if(transition=="unlock")registry.Suspend(true);HotkeyDispatch? nested=null;port.Now=200;port.BeforeFence=()=>nested=registry.Resolve(id,HotkeyPolicy.Parse("Ctrl+Q"),150);switch(transition){case "reconcile":registry.Reconcile(values,"v2");break;case "unlock":registry.Suspend(false);break;default:registry.Recover("v1");break;}Assert.Null(nested);Assert.Null(registry.Resolve(id,HotkeyPolicy.Parse("Ctrl+Q"),150));Assert.NotNull(registry.Resolve(id,HotkeyPolicy.Parse("Ctrl+Q"),201));}
    [Fact]public void FenceFailureCannotLeaveOldQueuedDispatchEligible()
    {var port=new Port();var registry=new HotkeyRegistry(port);registry.Restore(Map(("toggle","Ctrl+Q")),"v1");var prior=registry.Resolve(port.Owned.Single().Key,HotkeyPolicy.Parse("Ctrl+Q"),101)!;port.Failure=(op,_,_)=>op=="fence"?5:0;Assert.Throws<IOException>(()=>registry.Reconcile(Map(("toggle","Ctrl+Q")),"v2"));Assert.False(registry.Current(prior));Assert.Null(registry.Resolve(port.Owned.Single().Key,HotkeyPolicy.Parse("Ctrl+Q"),101));Assert.All(registry.Status,s=>Assert.True(s.RecoveryRequired));port.Failure=null;registry.Restore(Map(("toggle","Ctrl+Q")),"v2");Assert.All(registry.Status,s=>Assert.False(s.RecoveryRequired));}
    [Fact]public void RollbackFenceFailureIsUnconfirmedEvenWhenOldPhysicalSetWasRestored()
    {var port=new Port();var registry=new HotkeyRegistry(port);registry.Restore(Map(("toggle","Ctrl+Q")),"v1");var transaction=registry.Prepare(Map(("toggle","Ctrl+T")));port.Failure=(op,_,_)=>op=="fence"?5:0;Assert.Throws<AggregateException>(()=>registry.Rollback(transaction));Assert.Single(port.Owned);Assert.Equal(HotkeyPolicy.Parse("Ctrl+Q"),port.Owned.Single().Value);Assert.All(registry.Status,s=>Assert.True(s.RecoveryRequired));Assert.Null(registry.Resolve(port.Owned.Single().Key,HotkeyPolicy.Parse("Ctrl+Q"),101));}
    [Fact]public void RetiredRegistrationIdIsNeverReusedAndQueuedTicketCannotRebind()
    {var port=new Port();var registry=new HotkeyRegistry(port);registry.Restore(Map(("toggle","Ctrl+Q")),"v1");int old=port.Owned.Single().Key;var transaction=registry.Prepare(Map(("toggle","Ctrl+W")));registry.Commit(transaction,"v2");Assert.DoesNotContain(old,port.Owned.Keys);Assert.Null(registry.Resolve(old,HotkeyPolicy.Parse("Ctrl+Q"),101));}
}
